code_example:
#include <iostream>
#include <type_traits>

// Generic template function
template <typename T>
void printTypeInfo(T value) {
    std::cout << "Value: " << value << ", Type: " << typeid(T).name() << std::endl;
}

// Specialization for int type
template <>
void printTypeInfo<int>(int value) {
    std::cout << "Integer value: " << value << std::endl;
}

// SFINAE example: only enable for integral types
template <typename T>
typename std::enable_if<std::is_integral<T>::value>::type
printIfIntegral(T value) {
    std::cout << "Integral value: " << value << std::endl;
}

int main() {
    printTypeInfo(3.14); // double
    printTypeInfo(42);   // int
    printIfIntegral(100); // int, enabled
    // printIfIntegral(3.14); // Error: substitution failure, function not enabled for non-integral types
    return 0;
}
